<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Core\Auth;use App\Core\Crypto;use App\Core\Request;use App\Core\Response;use App\Models\AuditLog;use App\Models\User;final class AdminUserController extends AdminController{public function index(Request $C):Response{$b=User::castAll(User::query()->where('role',Auth::ADMIN_ROLES)->orderBy('id')->get());return $this->view('admin/admins',['admins'=>$b,'roles'=>Auth::ADMIN_ROLES,'meta'=>['title'=>t('admin.admins')]]);}public function save(Request $b):Response{if($H=$this->validate($b,['email'=>'required|email','name'=>'required|max:191','role'=>'required|in:editor,support,admin,superadmin'],'/admin/admins')){return $H;}$f=$b->str('role');if($f==='superadmin'&&Auth::role()!=='superadmin'){$this->flash('error',t('error.403'));return $this->redirect('/admin/admins');}$h=$b->int('id');$T=User::findByEmail($b->str('email'));$M=['name'=>$b->str('name'),'role'=>$f,'is_active'=>$b->bool('is_active')?1:0];$d=(string)$b->input('password','');if($d!==''){if(mb_strlen($d)<12){$this->flash('error',t('validation.password',['field'=>t('field.password')]));return $this->redirect('/admin/admins');}$M['password_hash']=Crypto::hashPassword($d);}if($h){$L=User::find($h);if(!$L||$L['role']==='superadmin'&&Auth::role()!=='superadmin'){return $this->redirect('/admin/admins');}if((int)$L['id']===Auth::id()){unset($M['role'],$M['is_active']);}if($T&&(int)$T['id']!==$h){$this->flash('error',t('auth.email_taken'));return $this->redirect('/admin/admins');}$M['email']=mb_strtolower($b->str('email'));User::update($h,$M);}else{if($T){$this->flash('error',t('auth.email_taken'));return $this->redirect('/admin/admins');}if($d===''){$d=bin2hex(random_bytes(9));}$h=User::register($b->str('email'),$d,$b->str('name'),lang(),$f,['email_verified_at'=>now()]);$this->flash('info',t('admin.temp_password').' '.$d);}AuditLog::log('admin.admin_save',$b->str('email'),['role'=>$f]);$this->flash('success',t('common.saved'));return $this->redirect('/admin/admins');}public function delete(Request $H,string $e):Response{$K=User::find((int)$e);if($K&&(int)$K['id']!==Auth::id()&&($K['role']!=='superadmin'||Auth::role()==='superadmin')){User::update((int)$e,['role'=>'customer','is_active'=>0]);AuditLog::log('admin.admin_delete',$K['email']);$this->flash('success',t('common.deleted'));}return $this->redirect('/admin/admins');}}